const SIZE=REGION_CELL,rule={mode:'walk',collision:0,elevation:3,behavior:0,layerType:1};
export const regionExit=e=>({x:e==='west'?0:e==='east'?63:32,y:e==='north'?0:e==='south'?63:32});
export function routeRoad(node){const random=randomFor(node.seed),hub={x:20+Math.floor(random()*24),y:20+Math.floor(random()*24)},line=new Set();for(const e of node.exits){let{x,y}=regionExit(e.edge);line.add(y*SIZE+x);for(const axis of (['west','east'].includes(e.edge)?['x','y']:['y','x']))while((axis==='x'?x:y)!==hub[axis]){if(axis==='x')x+=Math.sign(hub.x-x);else y+=Math.sign(hub.y-y);line.add(y*SIZE+x);}}if(node.exits.length>1){const protectedCells=new Set(node.exits.map(e=>{const p=regionExit(e.edge);return p.y*SIZE+p.x;})),neighbours=i=>[i%SIZE?i-1:-1,i%SIZE<SIZE-1?i+1:-1,i-SIZE,i+SIZE].filter(j=>line.has(j)),todo=[...line].filter(i=>!protectedCells.has(i)&&neighbours(i).length<2);while(todo.length){const i=todo.pop();if(!line.has(i)||protectedCells.has(i)||neighbours(i).length>1)continue;const adjacent=neighbours(i);line.delete(i);todo.push(...adjacent);}}const road=new Set();for(const i of line){const x=i%SIZE,y=Math.floor(i/SIZE);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=x+dx,yy=y+dy;if(xx>=0&&yy>=0&&xx<SIZE&&yy<SIZE)road.add(yy*SIZE+xx);}}return road;}
function pathMask(road,x,y,exits){let bits=0;for(const[dx,dy,bit]of[[0,-1,1],[1,0,2],[0,1,4],[-1,0,8],[1,-1,16],[1,1,32],[-1,1,64],[-1,-1,128]]){const xx=x+dx,yy=y+dy,inside=xx>=0&&yy>=0&&xx<SIZE&&yy<SIZE,beyond=exits.some(e=>e.edge==='north'&&yy===-1&&Math.abs(xx-32)<=1||e.edge==='south'&&yy===SIZE&&Math.abs(xx-32)<=1||e.edge==='west'&&xx===-1&&Math.abs(yy-32)<=1||e.edge==='east'&&xx===SIZE&&Math.abs(yy-32)<=1);if(inside&&road.has(yy*SIZE+xx)||beyond)bits|=bit;}return MASKS.indexOf(normalizeMask(bits));}
function drawPath(map,road,path,exits,edgesOnly=false){for(const i of road){const x=i%SIZE,y=Math.floor(i/SIZE);if(edgesOnly&&x>1&&y>1&&x<62&&y<62)continue;const v=pathMask(road,x,y,exits);map.layers.ground[i]={a:path,sx:v%8*16,sy:Math.floor(v/8)*16,size:16};map.movement[i]={...rule};}}
function makeRoute(project,node,library,profile,reader,sourceId){
 const map=newMap(node.name,SIZE,SIZE),base=reader&&(sourceId===profile.sha256&&reader.byKey(profile.baseKey)||reader.maps.find(m=>m.type===1));map.rom={generated:true,sourceId:sourceId||null,templateKey:base?.key||null,engine:reader?.engine||'frlg',metatileLayers:reader?.metatileLayers||2,layerAtlasIds:[],originalWidth:0,originalHeight:0,originalBlocks:[],events:{npcs:[],warps:[],signs:[],triggers:[]},connections:[],connectedEvents:[],mapType:3};const road=routeRoad(node),kit=profile.terrain;map.movement=Array.from({length:4096},()=>({...rule}));map.layers.ground=Array.from({length:4096},()=>({a:kit.floor,sx:0,sy:0,size:16}));drawPath(map,road,kit.path,node.exits);map.generator={type:'region-route',version:1,seed:node.seed,theme:node.biome,exits:node.exits.map(e=>({...e,...regionExit(e.edge)})),decorations:{trees:0}};
 const templates=[],plants=id=>library.templates.filter(t=>t.bundled&&t.profileId===id&&/Trees & plants$/.test(t.category)&&t.w<=3&&t.h>=2&&t.h<=4),local=plants(profile.id),pool=local.length?local:plants('firered');if(!pool.length)throw Error('No complete tree artwork is available.');const fake={...project,maps:[map],links:[]},random=randomFor(node.seed^0x39abcd);
 // Every chunk is divisible by four: complete objects stay inside its boundaries.
 for(let y=0;y<SIZE;y+=4)for(let x=0;x<SIZE;x+=4){const boundary=x===0||y===0||x===60||y===60;if(!boundary&&random()>(node.biome==='forest'?.68:.23))continue;const t=adaptSettlementTemplate(pool[Math.floor(random()*pool.length)],map.rom.metatileLayers);let clear=true;for(let yy=Math.max(0,y-2);yy<Math.min(SIZE,y+6);yy++)for(let xx=Math.max(0,x-2);xx<Math.min(SIZE,x+6);xx++)if(road.has(yy*SIZE+xx))clear=false;if(!clear)continue;const px=boundary?x:x+Math.floor(random()*(5-t.w)),py=boundary?y:y+Math.floor(random()*(5-t.h));if(px+t.w>SIZE||py+t.h>SIZE)continue;const a=placeAssembly(fake,map,t,px,py);if(!templates.some(q=>q.id===t.id))templates.push(t);map.generator.decorations.trees++;if(boundary)map.generator.borderPattern??={assemblyId:a.id,x,y,w:t.w,h:t.h};}
 for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++)if((!x||!y||x===63||y===63)&&!road.has(y*SIZE+x)){const i=y*SIZE+x;map.movement[i]={...rule,mode:'block',collision:1};const a=map.nativeAssemblies?.find(a=>x>=a.x&&y>=a.y&&x<a.x+a.w&&y<a.y+a.h);if(a){a.expected.rules[(y-a.y)*a.w+x-a.x]=structuredClone(map.movement[i]);a.before.movement[(y-a.y)*a.w+x-a.x]=structuredClone(map.movement[i]);}}
 return{maps:[map],links:[],assets:[],templates};
}
function entrances(map,links){const points=[];for(const a of map.nativeAssemblies||[])for(const e of a.entrances||[])points.push({x:a.x+e.x,y:a.y+e.y,label:a.name+' entrance'});for(const l of links)for(const end of ['from','to'])if(l[end].mapId===map.id)points.push({...l[end],label:l.seam?'Scrolling exit':'Interior entrance'});return points;}
export async function generateRegion(project,reader,sourceId,{plan=planRegion(),styles=['firered'],terrainStyle='firered',interiors=true,facilities=['centre','mart'],signal,progress=()=>{}}={}){
 validateRegionPlan(plan);if(!Array.isArray(styles)||!styles.length)throw Error('Choose at least one building source.');if(!Array.isArray(facilities)||facilities.some(k=>!['centre','mart','gym'].includes(k)))throw Error('Choose Centres, marts or gyms.');const library=await readSettlementLibrary();for(const id of styles)if(!library.profiles.some(p=>p.id===id))throw Error('Choose included building sources.');const profile=library.profiles.find(p=>p.id===terrainStyle&&p.terrain);if(!profile)throw Error('Choose an included terrain source.');if(project.maps.length+plan.nodes.length>80)throw Error('There is not enough room for these outdoor maps.');
 const work={maps:[],links:[],assets:[],templates:[],findings:[]},knownAssets=new Set(project.assets.map(a=>a.id)),knownTemplates=new Set((project.romObjects||[]).map(t=>t.id)),assetsBy=new Map(library.assets.map(a=>[a.id,a])),locations=new Map(),regionId=uid(),abort=()=>{if(signal?.aborted)throw Error('Region generation cancelled. Your project has not changed.');},merged=()=>({...project,maps:[...project.maps,...work.maps],links:[...project.links,...work.links],assets:[...project.assets,...work.assets],romObjects:[...project.romObjects||[],...work.templates]});
 const addAsset=a=>{if(!a)throw Error('A region image is missing.');assetsBy.set(a.id,a);if(!knownAssets.has(a.id)){knownAssets.add(a.id);work.assets.push(a);}};
 for(let i=0;i<plan.nodes.length;i++){
  abort();const n=plan.nodes[i];progress('Building '+n.name+' · '+(i+1)+' / '+plan.nodes.length);await new Promise(r=>setTimeout(r,0));abort();let bundle;
  if(n.kind==='settlement'){let failure;for(let attempt=0;attempt<3;attempt++){abort();try{bundle=await generateSettlement(merged(),reader,sourceId,profile,{name:n.name,seed:(n.seed+Math.imul(attempt,0x9e3779b9))>>>0,preset:n.biome+'-'+plan.settlementSize,styles,facilities,exits:n.exits,features:{water:false},interiors,bounds:{width:SIZE,height:SIZE}});checkGenerationAccess(bundle.maps[0],[...n.exits.map(e=>({...regionExit(e.edge),label:e.edge+' exit'})),...entrances(bundle.maps[0],bundle.links)]);break;}catch(e){failure=e;bundle=null;}}if(!bundle)throw Error(n.name+' failed three layouts: '+failure.message);
  }else bundle=makeRoute(merged(),n,library,profile,reader,sourceId);
  const map=bundle.maps[0];if(map.width!==SIZE||map.height!==SIZE)throw Error('A settlement exceeded its reserved bounds.');if(n.kind==='settlement'){const road=new Set();for(let j=0;j<4096;j++)if(map.layers.ground[j]?.a===profile.terrain.path)road.add(j);drawPath(map,road,profile.terrain.path,n.exits,true);}
  map.world={x:n.x*280,y:n.y*240};map.region={id:regionId,nodeId:n.id,x:n.x,y:n.y,seed:plan.seed};map.notes+=' Region seed '+plan.seed+'. Scrolling exits are connected; playtest before exporting.';locations.set(n.id,map);for(let j=1;j<bundle.maps.length;j++)bundle.maps[j].world={x:n.x*280+30+j%3*50,y:n.y*240+160+Math.floor(j/3)*35};
  bundle.assets.forEach(addAsset);const ids=new Set();for(const m of bundle.maps){for(const cells of Object.values(m.layers))for(const t of cells)if(t)ids.add(t.a);for(const a of m.nativeAssemblies||[])for(const id of a.overlay?.planeAssetIds||[])ids.add(id);for(const o of m.objects)ids.add(o.assetId);for(const n of m.markers)if(n.npc)ids.add(n.npc.assetId);}for(const t of bundle.templates)for(const id of t.overlay?.planeAssetIds||[])ids.add(id);for(const id of ids)if(!knownAssets.has(id))addAsset(assetsBy.get(id));
  work.maps.push(...bundle.maps);work.links.push(...bundle.links);for(const t of bundle.templates)if(!knownTemplates.has(t.id)){knownTemplates.add(t.id);work.templates.push(t);}
  if(project.maps.length+work.maps.length>80||project.assets.length+work.assets.length>512||project.maps.reduce((n,m)=>n+m.width*m.height,0)+work.maps.reduce((n,m)=>n+m.width*m.height,0)>400000)throw Error('This region exceeds the project limits. Use fewer locations or turn off interiors.');
 }
 abort();progress('Checking scrolling connections and entrances');for(const e of plan.edges){const a=locations.get(e.from),b=locations.get(e.to);saveSeamLink(work,{from:{mapId:a.id},to:{mapId:b.id},seam:{direction:e.direction,offset:0},label:a.name+' ↔ '+b.name,twoWay:true});}
 const checks=[];for(const m of work.maps){const access=checkGenerationAccess(m,entrances(m,work.links)),findings=checkMap(work,m);if(findings.some(f=>f.severity==='error'))throw Error(m.name+' failed the complete-object check.');checks.push({name:m.name,...access});work.findings.push(...findings.map(f=>({...f,mapName:m.name,mapId:m.id})));}
 abort();if((project.romObjects||[]).length+work.templates.length>512||project.links.length+work.links.length>2000)throw Error('This region exceeds the object or connection limit.');const start=locations.get(plan.nodes.find(n=>n.kind==='settlement').id);start.region.plan=structuredClone(plan);
 return{...work,plan:structuredClone(plan),startMapId:start.id,report:{outdoorMaps:plan.nodes.length,settlements:plan.nodes.filter(n=>n.kind==='settlement').length,interiors:work.maps.length-plan.nodes.length,scrollingConnections:plan.edges.length,checks}};
}
